// entities/vectorindex/hnsw/config.go lines 28-29
DefaultEF = -1 // indicates "let Weaviate pick"

// adapters/repos/db/vector/hnsw/search.go lines 44-58
func (h *hnsw) searchTimeEF(k int) int {
  ef := int(atomic.LoadInt64(&h.ef))
  if ef < 1 {
    return h.autoEfFromK(k)  // ef=-1 triggers dynamic calculation
  }
  if ef < k {
    ef = k
  }
  return ef
}
